/** Contract-based test harness for the compute entry point
  *
  * @param api_actuationAuthority incoming data port
  * @param api_proposedRates incoming data port
  */
pub fn testComputeCB(
  api_actuationAuthority: bool,
  api_proposedRates: FlightStack::ProposedActuatorRates) -> HarnessResult
{
  // Initialize the app
  crate::actuatorSafetyGate_behavior_initialize();

  // [PutInPorts]: Set values on the input ports
  put_actuationAuthority(api_actuationAuthority);
  put_proposedRates(api_proposedRates);

  // [InvokeEntryPoint]: Invoke the entry point
  crate::actuatorSafetyGate_behavior_timeTriggered();

  return HarnessResult::Passed
}

